1→/* ── Reset & Base ──────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: #0f1117;
  color: #e0e0e0;
  min-height: 100vh;
}
10→
button { cursor: pointer; }
input, select, button { font-family: inherit; font-size: 0.9rem; }

.screen { display: none; }
.screen.active { display: block; }
[hidden] { display: none !important; }

/* ── Project List ─────────────────────────────────────────────────── */
#project-list-screen {
20→  max-width: 700px;
  margin: 0 auto;
  padding: 60px 20px;
  text-align: center;
}

#project-list-screen h1 {
  font-size: 2.4rem;
  color: #fff;
  letter-spacing: 2px;
30→}

.subtitle {
  color: #888;
  margin-bottom: 40px;
}

.project-controls {
  display: flex;
  gap: 10px;
40→  margin-bottom: 30px;
}

