/* ── Project List ─────────────────────────────────────────────────── */
#project-list-screen {
  max-width: 700px;
  margin: 0 auto;
  padding: 60px 20px;
  text-align: center;
}

#project-list-screen h1 {
  font-size: 2.4rem;
  color: #fff;
  letter-spacing: 2px;
}

.subtitle {
  color: #888;
  margin-bottom: 40px;
}

.project-controls {
  display: flex;
  gap: 10px;
  margin-bottom: 30px;
}

.project-controls input {
  flex: 1;
  min-width: 0;
  padding: 10px 14px;
  border-radius: 6px;
  border: 1px solid #333;
  background: #1a1d27;
  color: #fff;
}

.project-controls button {
  padding: 10px 20px;
  border: none;
  border-radius: 6px;
  background: #3498db;
  color: #fff;
  font-weight: 600;
}

.project-controls button:hover { background: #2980b9; }

.project-search-row { flex-wrap: wrap; margin-bottom: 12px; }
.project-search-row input::-webkit-search-cancel-button { -webkit-appearance: none; appearance: none; display: none; }
.project-search-row button { background: #22263a; }
.project-search-row button:hover { background: #2a2d3a; }
.project-search-row .preset-keys { align-self: center; }
#project-sort-status { align-self: center; color: #888; font-size: 0.9rem; }
#project-search-count, #project-search-empty, #projects-empty { color: #888; font-size: 0.9rem; margin: 0 0 16px; }

.project-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 20px;
  background: #1a1d27;
  border-radius: 8px;
  margin-bottom: 10px;
  cursor: pointer;
  transition: background 0.15s;
}

.project-card:hover { background: #22263a; }

.project-card .name { font-weight: 600; font-size: 1.05rem; }

.project-card .meta { color: #888; font-size: 0.85rem; }

